import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "./firebase";
import Table from "react-bootstrap/Table";
import Container from "react-bootstrap/Container";

const LogAttivita = () => {
  const [log, setLog] = useState([]);

  useEffect(() => {
    const fetchLog = async () => {
      try {
        const snapshot = await getDocs(collection(db, "log"));
        const dati = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

        const ordinati = dati.sort((a, b) => {
          const aTime = a.timestamp?.seconds || 0;
          const bTime = b.timestamp?.seconds || 0;
          return bTime - aTime;
        });

        setLog(ordinati);
      } catch (error) {
        console.error("Errore nel caricamento del log:", error);
      }
    };

    fetchLog();
  }, []);

  const formatData = (timestamp) => {
    if (!timestamp || !timestamp.seconds) return "—";
    const date = new Date(timestamp.seconds * 1000);
    return date.toLocaleString("it-IT");
  };

  return (
    <Container className="mt-4">
      <h3 className="mb-4">📁 Registro Attività</h3>
      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Data</th>
            <th>Utente</th>
            <th>Azione</th>
            <th>Target</th>
          </tr>
        </thead>
        <tbody>
          {log.length > 0 ? (
            log.map((entry) => (
              <tr key={entry.id}>
                <td>{formatData(entry.timestamp)}</td>
                <td>{entry.email || "—"}</td>
                <td>{entry.azione || "—"}</td>
                <td>{entry.target || "—"}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="4" className="text-center text-muted">
                Nessuna attività registrata.
              </td>
            </tr>
          )}
        </tbody>
      </Table>
    </Container>
  );
};

export default LogAttivita;